import { validateDate } from '../finance/amortization';
import { todayBogota } from '../finance/engine';
import { add, money, toCents } from '../finance/money';
import { validateCashSupport } from '../finance/cash';
import { findCashCategory } from '../finance/cash-catalog';
import type { Actor, Money, Support } from '../finance/types';
import { addQuantity, fromMicros, quantity, quantityValue, subtractQuantity, toMicros, validateItemQuantity } from './quantity';
import type { InventoryAlert, InventoryCount, InventoryItem, InventoryLine, InventoryLot, InventoryLotConformity, InventoryMovement, InventoryOrigin, InventoryPurchaseInput, InventoryReport, InventoryReportInput, InventorySale, InventoryState, InventoryType, InventoryWorkspace, Quantity } from './types';

const id=()=>crypto.randomUUID();const now=()=>new Date().toISOString();
export const INVENTORY_TYPE_LABELS:Record<InventoryType,string>={asset:'Propiedad, planta y equipo',raw_material:'Materia prima',supply:'Insumos de fabricación',scrap:'Chatarra',finished:'Producto terminado'};
const TYPES=Object.keys(INVENTORY_TYPE_LABELS) as InventoryType[];
export function createEmptyInventoryState(locationId='sede-principal'):InventoryState{return {version:1,warehouses:[{id:`inventory-main-${locationId}`,name:'Bodega Principal',locationId,active:true},{id:`inventory-dispatch-${locationId}`,name:'Bodega Despachos',locationId,active:true}],items:[],origins:[],movements:[],lots:[],counts:[],prices:[],sales:[],collections:[],supplierOffsets:[],warranties:[],scrapPreparations:[],scrapDispatches:[],requests:[],alerts:[],monthClosures:[]};}
export function getInventoryState(state:InventoryWorkspace):InventoryState{return state.inventory??createEmptyInventoryState(state.locations[0]?.id??'sede-principal');}
export function inventoryItemEffectiveDate(state:InventoryWorkspace,product:InventoryItem):string{const inventory=getInventoryState(state);const dates=[...inventory.origins.filter(row=>row.status==='posted'&&row.lines.some(line=>line.itemId===product.id)).map(row=>row.date),...inventory.movements.filter(row=>row.itemId===product.id).map(row=>row.date)];return dates.sort()[0]??product.createdAt.slice(0,10);}
function copy(state:InventoryWorkspace):InventoryWorkspace&{inventory:InventoryState}{const next=structuredClone(state);return Object.assign(next,{inventory:structuredClone(getInventoryState(state))});}
function text(value:string,label:string,min=1):string{if(typeof value!=='string'||value.trim().length<min||value.length>2000)throw new Error(`${label} es obligatorio y admite hasta 2000 caracteres.`);return value.trim();}
function date(value:string):void{validateDate(value);if(value>todayBogota())throw new Error('La fecha efectiva de Inventarios no puede ser futura.');}
function auth(state:InventoryWorkspace,actor:Actor,locationId?:string,roles=['owner','admin','inventory','production','sales','accounting','treasury']):void{const member=state.members.find(row=>row.id===actor.id&&row.active&&row.role===actor.role&&row.name===actor.name);if(!member||!roles.includes(member.role))throw new Error('No tienes permiso para esta operación de Inventarios.');if(locationId&&!member.locationIds.includes(locationId))throw new Error('No tienes permiso en esta sede.');}
function audit(state:InventoryWorkspace,actor:Actor,action:string,entityId:string,reason:string,before?:unknown,after?:unknown):void{const snapshot=(value:unknown)=>JSON.stringify(value,(key,item)=>key==='dataUrl'?'[archivo conservado en evidencia]':item).slice(0,2000);state.audit.unshift({id:id(),action,entityType:'inventory',entityId,actorId:actor.id,actorName:actor.name,timestamp:now(),reason:reason.slice(0,2000),before:before===undefined?undefined:snapshot(before),after:after===undefined?undefined:snapshot(after)});}
function support(value:Support,photo=false):void{if(!value)throw new Error('El acta o comprobante es obligatorio.');validateCashSupport(value);if(!value.dataUrl)throw new Error('Adjunta el archivo del acta o comprobante.');if(photo&&!value.type.startsWith('image/'))throw new Error('Se requiere una fotografía del elemento.');}
function item(state:InventoryWorkspace,itemId:string):InventoryItem{const result=getInventoryState(state).items.find(row=>row.id===itemId&&row.active);if(!result)throw new Error('La referencia no existe o está inactiva.');return result;}
function warehouse(state:InventoryWorkspace,warehouseId:string,actor?:Actor){const result=getInventoryState(state).warehouses.find(row=>row.id===warehouseId&&row.active);if(!result)throw new Error('La bodega no existe o está inactiva.');if(actor)auth(state,actor,result.locationId);return result;}
export function inventoryMonthBounds(month:string):{startDate:string;endDate:string}{if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(month))throw new Error('El mes debe usar formato AAAA-MM.');validateDate(`${month}-01`);return {startDate:`${month}-01`,endDate:new Date(Date.UTC(Number(month.slice(0,4)),Number(month.slice(5,7)),0)).toISOString().slice(0,10)};}
function writable(state:InventoryWorkspace,type:InventoryType,effectiveDate:string):void{date(effectiveDate);if(getInventoryState(state).monthClosures.some(row=>row.inventoryType===type&&row.month>=effectiveDate.slice(0,7)))throw new Error('El período de este inventario está cerrado. Solicita autorización institucional; facturas y lotes cerrados requieren exclusivamente CREADOR.');}
function checkedLines(state:InventoryWorkspace,lines:InventoryLine[],actor:Actor,effectiveDate:string,allowed:InventoryType[],zero=false):InventoryLine[]{if(!Array.isArray(lines)||lines.length>1000||!lines.length)throw new Error('Incluye entre 1 y 1000 referencias.');const seen=new Set<string>();return lines.map(row=>{const product=item(state,row.itemId);warehouse(state,row.warehouseId,actor);if(!allowed.includes(product.inventoryType))throw new Error('La referencia no corresponde al inventario de esta operación.');writable(state,product.inventoryType,effectiveDate);const key=`${row.itemId}:${row.warehouseId}`;if(seen.has(key))throw new Error('La operación repite una referencia en la misma bodega.');seen.add(key);const result={...row,quantity:validateItemQuantity(product,row.quantity,!zero),unitValue:row.unitValue===undefined?undefined:money(row.unitValue)};if(result.unitValue!==undefined&&toCents(result.unitValue)<0n)throw new Error('El valor unitario no puede ser negativo.');return result;});}
export function getInventoryStock(state:InventoryWorkspace,input:{itemId:string;warehouseId:string;asOfDate?:string}):{theoretical:Quantity;available:Quantity;reserved:Quantity;quarantine:Quantity}{const inventory=getInventoryState(state);const cutoff=input.asOfDate??todayBogota();validateDate(cutoff);let balance=0n;for(const row of inventory.movements.filter(row=>row.itemId===input.itemId&&row.warehouseId===input.warehouseId&&row.date<=cutoff))balance+=toMicros(row.quantity)*(row.direction==='in'?1n:-1n);const reserved=inventory.scrapPreparations.filter(row=>row.itemId===input.itemId&&row.warehouseId===input.warehouseId&&row.date<=cutoff&&(!row.dispatchId||!inventory.scrapDispatches.some(dispatch=>dispatch.id===row.dispatchId&&dispatch.date<=cutoff))).reduce((sum,row)=>sum+toMicros(row.quantity),0n);const quarantine=inventory.warranties.filter(row=>row.itemId===input.itemId&&row.warehouseId===input.warehouseId&&row.date<=cutoff&&(!row.disposedAt||row.disposedAt.slice(0,10)>cutoff)).reduce((sum,row)=>sum+toMicros(row.quantity),0n);return {theoretical:fromMicros(balance),available:fromMicros(balance-reserved),reserved:fromMicros(reserved),quarantine:fromMicros(quarantine)};}
function movement(state:InventoryWorkspace&{inventory:InventoryState},line:InventoryLine,actor:Actor,input:{date:string;direction:'in'|'out';kind:InventoryMovement['kind'];sourceKey:string;sourceReference:string;responsible:string;support?:Support;notes?:string;totalValue?:Money;cashTransactionId?:string},ownReservation=0n):void{if(state.inventory.movements.some(row=>row.sourceKey===input.sourceKey))throw new Error('Este documento o renglón ya se incorporó al inventario.');const product=item(state,line.itemId);if(input.kind!=='origin'&&!state.inventory.origins.some(row=>row.inventoryType===product.inventoryType&&row.status==='posted'&&row.date<=input.date))throw new Error('Registra y confirma primero el ORIGEN único de este inventario, incluso si su saldo es cero.');if(product.inventoryType==='asset'&&input.direction==='in'&&(line.quantity!=='1.000000'||state.inventory.movements.some(row=>row.itemId===line.itemId&&row.direction==='in')))throw new Error('Cada código de activo representa una sola unidad histórica; no puede duplicarse ni reutilizarse.');if(input.direction==='out'&&toMicros(getInventoryStock(state,{...line,asOfDate:input.date}).available)+ownReservation<toMicros(line.quantity))throw new Error('No hay existencias disponibles suficientes en la bodega indicada.');if(input.direction==='out'&&state.inventory.movements.some(row=>row.itemId===line.itemId&&row.warehouseId===line.warehouseId&&row.date>input.date))throw new Error('La salida no puede retroceder antes de movimientos posteriores: solicita revisión histórica.');state.inventory.movements.push({...line,...input,quantity:quantity(line.quantity),notes:input.notes?.trim()??'',id:id(),inventoryType:product.inventoryType,actorId:actor.id,createdAt:now()});}

export function createInventoryItem(state:InventoryWorkspace,input:Omit<InventoryItem,'id'|'createdBy'|'createdAt'>,actor:Actor):InventoryWorkspace{auth(state,actor);if(!TYPES.includes(input.inventoryType)||!['unit','kg','m','l'].includes(input.unit))throw new Error('Tipo o unidad de inventario inválidos.');const code=text(input.code,'El código').toLocaleUpperCase('es-CO');if(getInventoryState(state).items.some(row=>row.code.toLocaleUpperCase('es-CO')===code))throw new Error('El código o SKU ya existe.');text(input.description,'La descripción');text(input.category,'La categoría');if(typeof input.active!=='boolean')throw new Error('El estado de la referencia es inválido.');if(input.inventoryType==='asset'){support(input.photo!,true);text(input.condition??'','El estado o condición');if(input.unit!=='unit'||input.unitValue===undefined)throw new Error('El activo requiere unidades enteras y valor documentado.');}if(input.inventoryType==='finished'&&input.unit!=='unit')throw new Error('El producto terminado se administra en unidades enteras.');if(input.unitValue!==undefined&&toCents(money(input.unitValue))<0n)throw new Error('El valor no puede ser negativo.');const next=copy(state);const record={...input,code,description:input.description.trim(),id:id(),createdBy:actor.id,createdAt:now(),unitValue:input.unitValue===undefined?undefined:money(input.unitValue)};next.inventory.items.push(record);audit(next,actor,'Referencia de inventario creada',record.id,code,undefined,record);return next;}

export function saveInventoryOriginDraft(state:InventoryWorkspace,input:{inventoryType:InventoryType;date:string;sourceReference:string;responsible:string;support:Support;lines:InventoryLine[]},actor:Actor):InventoryWorkspace{auth(state,actor);writable(state,input.inventoryType,input.date);support(input.support);text(input.sourceReference,'La referencia del ORIGEN');text(input.responsible,'El responsable');const inventory=getInventoryState(state);const previous=inventory.origins.find(row=>row.inventoryType===input.inventoryType);if(previous?.status==='posted')throw new Error('Este inventario ya tiene ORIGEN histórico. Una omisión requiere autorización institucional.');const lines=input.lines.length?checkedLines(state,input.lines,actor,input.date,[input.inventoryType],true):[];const next=copy(state);const record:InventoryOrigin={...input,lines,id:previous?.id??id(),status:'draft',createdBy:previous?.createdBy??actor.id,createdAt:previous?.createdAt??now()};if(previous)next.inventory.origins=next.inventory.origins.map(row=>row.id===previous.id?record:row);else next.inventory.origins.push(record);audit(next,actor,'Borrador de ORIGEN conservado',record.id,input.sourceReference,previous,record);return next;}
export function postInventoryOrigin(state:InventoryWorkspace,originId:string,actor:Actor):InventoryWorkspace{const origin=getInventoryState(state).origins.find(row=>row.id===originId);if(!origin||origin.status!=='draft')throw new Error('El ORIGEN no es un borrador disponible.');auth(state,actor);writable(state,origin.inventoryType,origin.date);if(getInventoryState(state).movements.some(row=>row.inventoryType===origin.inventoryType))throw new Error('El ORIGEN no puede agregarse después de movimientos operativos.');const expected=getInventoryState(state).items.filter(row=>row.inventoryType===origin.inventoryType&&row.active).flatMap(product=>getInventoryState(state).warehouses.filter(row=>row.active).map(location=>`${product.id}:${location.id}`));if(expected.some(key=>!origin.lines.some(row=>`${row.itemId}:${row.warehouseId}`===key))||expected.length!==origin.lines.length)throw new Error('Cuenta todas las referencias y bodegas del ORIGEN; registra cero explícito en las posiciones vacías.');const next=copy(state);for(const [index,line]of origin.lines.entries()){warehouse(state,line.warehouseId,actor);if(toMicros(line.quantity)>0n)movement(next,line,actor,{date:origin.date,direction:'in',kind:'origin',sourceKey:`origin:${origin.id}:${index}`,sourceReference:origin.sourceReference,responsible:origin.responsible,support:origin.support,totalValue:line.unitValue===undefined?undefined:quantityValue(line.quantity,line.unitValue)});}const record=next.inventory.origins.find(row=>row.id===origin.id)!;record.status='posted';record.postedAt=now();audit(next,actor,'ORIGEN incorporado una sola vez',record.id,origin.sourceReference,origin,record);return next;}

export function receiveInventoryPurchase(state:InventoryWorkspace,input:InventoryPurchaseInput,actor:Actor):InventoryWorkspace{auth(state,actor);support(input.support);text(input.supplier,'El proveedor');const cash=state.transactions.find(row=>row.id===input.cashTransactionId&&row.status==='posted'&&!row.reversedBy&&row.kind==='expense');if(!cash)throw new Error('La compra requiere una salida real y vigente registrada en Caja.');if(getInventoryState(state).movements.some(row=>row.cashTransactionId===cash.id))throw new Error('La compra de Caja ya fue recibida; no se puede duplicar el alta.');if(input.date<cash.date)throw new Error('La recepción no puede ser anterior al comprobante de adquisición.');const lines=checkedLines(state,input.lines,actor,input.date,['asset','raw_material','supply']);if(cash.party.trim().toLocaleLowerCase('es-CO')!==input.supplier.trim().toLocaleLowerCase('es-CO'))throw new Error('El proveedor debe coincidir con el tercero de Caja.');const category=findCashCategory(state.cash?.metadata.find(row=>row.transactionId===cash.id)?.categoryId??cash.category);for(const line of lines){if(warehouse(state,line.warehouseId).locationId!==cash.locationId)throw new Error('La bodega no corresponde a la sede del comprobante de Caja.');const type=item(state,line.itemId).inventoryType;if(type==='asset'?category?.id!=='nuevas-adquisiciones':category?.groupId!=='produccion-insumos')throw new Error('La categoría de Caja no corresponde a la adquisición de este inventario.');}if(add(...input.lines.map(row=>money(row.totalValue)))!==cash.amount)throw new Error('La suma de los valores con impuestos incluidos debe coincidir con la salida de Caja.');const next=copy(state);lines.forEach((line,index)=>{const totalValue=money(input.lines[index].totalValue);if(toCents(totalValue)<=0n)throw new Error('El valor de adquisición debe ser positivo.');if(item(state,line.itemId).inventoryType==='asset'&&line.quantity!=='1.000000')throw new Error('Cada código de activo debe representar una sola unidad.');movement(next,line,actor,{date:input.date,direction:'in',kind:'purchase',sourceKey:`cash:${cash.id}:${index}`,sourceReference:cash.reference,responsible:input.supplier,support:input.support,totalValue,cashTransactionId:cash.id,notes:input.notes});});audit(next,actor,'Compra recibida desde Caja sin nuevo egreso',cash.id,cash.reference,undefined,lines);return next;}

function productionMovement(state:InventoryWorkspace,input:{date:string;sourceReference:string;responsible:string;support:Support;lines:InventoryLine[];notes?:string},actor:Actor,kind:'consumption'|'scrap_generation'):InventoryWorkspace{auth(state,actor);text(input.sourceReference,'La referencia externa de Producción');text(input.responsible,'El responsable');support(input.support);const lines=checkedLines(state,input.lines,actor,input.date,kind==='consumption'?['raw_material','supply']:['scrap']);const source=`${kind}:${input.sourceReference}`;if(getInventoryState(state).movements.some(row=>row.sourceKey.startsWith(`${source}:`)))throw new Error('Esta referencia de Producción ya fue incorporada.');const next=copy(state);lines.forEach((line,index)=>movement(next,line,actor,{date:input.date,direction:kind==='consumption'?'out':'in',kind,sourceKey:`${source}:${index}`,sourceReference:input.sourceReference,responsible:input.responsible,support:input.support,notes:input.notes}));audit(next,actor,kind==='consumption'?'Consumo con referencia documental de Producción':'Chatarra generada con referencia documental de Producción',source,input.sourceReference,undefined,lines);return next;}
export function consumeInventory(state:InventoryWorkspace,input:Parameters<typeof productionMovement>[1],actor:Actor):InventoryWorkspace{return productionMovement(state,input,actor,'consumption');}
export function generateInventoryScrap(state:InventoryWorkspace,input:Parameters<typeof productionMovement>[1],actor:Actor):InventoryWorkspace{return productionMovement(state,input,actor,'scrap_generation');}

export function createProductionLot(state:InventoryWorkspace,input:{reference:string;date:string;lines:InventoryLine[];notes?:string},actor:Actor):InventoryWorkspace{auth(state,actor);const reference=text(input.reference,'La referencia del lote');if(getInventoryState(state).lots.some(row=>row.reference===reference))throw new Error('El lote ya existe.');const lines=checkedLines(state,input.lines,actor,input.date,['finished']);const next=copy(state);const record:InventoryLot={id:id(),reference,date:input.date,lines,notes:input.notes?.trim()??'',conformities:[],status:'pending',createdBy:actor.id,createdAt:now()};next.inventory.lots.push(record);audit(next,actor,'Lote documental registrado sin aumentar existencias',record.id,reference,undefined,record);return next;}
function sameLines(left:InventoryLine[],right:InventoryLine[]):boolean{const signature=(rows:InventoryLine[])=>rows.map(row=>`${row.itemId}|${row.warehouseId}|${quantity(row.quantity)}`).sort().join(';');return signature(left)===signature(right);}
export function recordLotConformity(state:InventoryWorkspace,input:{lotId:string;department:'production'|'sales';responsible:string;sourceReference:string;date:string;support:Support;lines:InventoryLine[]},actor:Actor):InventoryWorkspace{auth(state,actor);const lot=getInventoryState(state).lots.find(row=>row.id===input.lotId);if(!lot||lot.status==='accepted')throw new Error('El lote no está disponible para conformidad.');writable(state,'finished',lot.date);date(input.date);if(input.date<lot.date)throw new Error('La conformidad no puede ser anterior al lote.');if(!['production','sales'].includes(input.department))throw new Error('Selecciona Producción o Ventas.');text(input.responsible,'El responsable declarado');text(input.sourceReference,'La referencia documental');support(input.support);if(lot.conformities.some(row=>row.sourceReference===input.sourceReference))throw new Error('Las dos conformidades requieren referencias documentales distintas.');const lines=checkedLines(state,input.lines,actor,lot.date,['finished']);const next=copy(state);const record=next.inventory.lots.find(row=>row.id===lot.id)!;const conformity:InventoryLotConformity={...input,lines,recordedBy:actor.id,recordedAt:now()};record.conformities.push(conformity);const production=record.conformities.filter(row=>row.department==='production').at(-1);const sales=record.conformities.filter(row=>row.department==='sales').at(-1);record.status=production&&sales?(sameLines(production.lines,sales.lines)&&sameLines(lot.lines,production.lines)?'ready':'disputed'):'pending';audit(next,actor,'Conformidad documental registrada; no suplanta autenticación departamental',record.id,input.sourceReference,lot,record);return next;}
export function acceptProductionLot(state:InventoryWorkspace,lotId:string,actor:Actor):InventoryWorkspace{auth(state,actor);const lot=getInventoryState(state).lots.find(row=>row.id===lotId);if(!lot||lot.status!=='ready')throw new Error('El lote requiere dos conformidades documentadas coincidentes antes de incorporarse.');writable(state,'finished',lot.date);const lines=checkedLines(state,lot.lines,actor,lot.date,['finished']);const next=copy(state);lines.forEach((line,index)=>movement(next,line,actor,{date:lot.date,direction:'in',kind:'production',sourceKey:`lot:${lot.id}:${index}`,sourceReference:lot.reference,responsible:actor.name,notes:lot.notes}));const record=next.inventory.lots.find(row=>row.id===lot.id)!;record.status='accepted';record.acceptedAt=now();audit(next,actor,'Lote coincidente incorporado una sola vez',lot.id,lot.reference,lot,record);return next;}

export function recordInventoryCount(state:InventoryWorkspace,input:{inventoryType:InventoryType;date:string;purpose:'daily'|'monthly';responsible:string;support:Support;sourceReference:string;notes?:string;lines:InventoryLine[]},actor:Actor):InventoryWorkspace{auth(state,actor);support(input.support);text(input.responsible,'El responsable del acta');text(input.sourceReference,'La referencia del acta');if(!['daily','monthly'].includes(input.purpose)||input.purpose==='daily'&&input.inventoryType!=='finished')throw new Error('El conteo diario corresponde a producto terminado.');if(getInventoryState(state).counts.some(row=>row.sourceReference===input.sourceReference))throw new Error('Esta acta de conteo ya fue registrada.');const lines=input.lines.length?checkedLines(state,input.lines,actor,input.date,[input.inventoryType],true):[];writable(state,input.inventoryType,input.date);if(!lines.length&&getInventoryState(state).items.some(row=>row.active&&row.inventoryType===input.inventoryType))throw new Error('El acta debe contener las referencias del inventario.');const next=copy(state);const record:InventoryCount={...input,id:id(),notes:input.notes?.trim()??'',lines:lines.map(row=>{const theoretical=getInventoryStock(state,{...row,asOfDate:input.date}).theoretical;return {...row,theoretical,difference:subtractQuantity(row.quantity,theoretical)};}),movementIds:getInventoryState(state).movements.filter(row=>row.date<=input.date).map(row=>row.id),recordedBy:actor.id,createdAt:now()};next.inventory.counts.push(record);for(const line of record.lines.filter(row=>row.difference!=='0.000000')){const location=warehouse(state,line.warehouseId);const critical=input.inventoryType==='finished'&&toMicros(line.difference)<0n;next.inventory.alerts.push({id:`inventory-count:${record.id}:${line.itemId}:${line.warehouseId}`,type:'count_difference',title:critical?'Faltante crítico de producto terminado':'Diferencia de inventario físico',description:input.notes?.trim()||'Diferencia documentada; no genera ajuste de existencias.',severity:critical?'critical':'warning',priority:critical?2:3,date:input.date,itemId:line.itemId,warehouseId:line.warehouseId,locationId:location.locationId,quantity:line.difference,status:'open',history:[{date:now(),actorId:actor.id,action:'Acta física registrada sin ajustar existencias'}]});}audit(next,actor,'Acta de conteo conservada sin ajustar inventario',record.id,input.sourceReference,undefined,record);return next;}

export function registerInventorySale(state:InventoryWorkspace,input:{reference:string;date:string;buyer:string;lines:(InventoryLine&{unitPrice:Money})[];support:Support;notes?:string},actor:Actor):InventoryWorkspace{auth(state,actor);support(input.support);const reference=text(input.reference,'La factura externa');text(input.buyer,'El comprador');if(getInventoryState(state).sales.some(row=>row.reference===reference))throw new Error('La factura ya fue registrada; no se duplican las salidas.');const checked=checkedLines(state,input.lines,actor,input.date,['finished','asset']);const type=item(state,checked[0].itemId).inventoryType;if(checked.some(row=>item(state,row.itemId).inventoryType!==type))throw new Error('La factura de este registro debe corresponder a un mismo inventario.');const next=copy(state);const lines=checked.map((row,index)=>{const unitPrice=money(input.lines[index].unitPrice);if(toCents(unitPrice)<0n)throw new Error('El precio no puede ser negativo.');return {...row,unitPrice,totalValue:quantityValue(row.quantity,unitPrice)};});const sale:InventorySale={id:id(),reference,date:input.date,buyer:input.buyer.trim(),lines,support:input.support,totalValue:add(...lines.map(row=>row.totalValue)),kind:type as 'asset'|'finished',sourceReference:reference,notes:input.notes?.trim()??'',settlements:[],createdBy:actor.id,createdAt:now()};lines.forEach((line,index)=>movement(next,line,actor,{date:input.date,direction:'out',kind:'sale',sourceKey:`sale:${sale.id}:${index}`,sourceReference:reference,responsible:input.buyer,support:input.support,totalValue:line.totalValue,notes:input.notes}));next.inventory.sales.push(sale);audit(next,actor,'Salida vinculada a factura externa; sin crear documento de Ventas ni recaudo',sale.id,reference,undefined,sale);return next;}
export function recordInventoryWarranty(state:InventoryWorkspace,input:{saleId:string;itemId:string;warehouseId:string;quantity:Quantity;date:string;photo:Support;reason:string;responsible:string},actor:Actor):InventoryWorkspace{auth(state,actor);const sale=getInventoryState(state).sales.find(row=>row.id===input.saleId&&row.kind==='finished');if(!sale)throw new Error('La garantía debe vincular una venta de producto terminado existente.');const product=item(state,input.itemId);warehouse(state,input.warehouseId,actor);writable(state,'finished',input.date);support(input.photo,true);text(input.reason,'El motivo de garantía',5);text(input.responsible,'El responsable');const qty=validateItemQuantity(product,input.quantity);const sold=addQuantity(...sale.lines.filter(row=>row.itemId===input.itemId).map(row=>row.quantity));const prior=addQuantity(...getInventoryState(state).warranties.filter(row=>row.saleId===sale.id&&row.itemId===product.id).map(row=>row.quantity));if(input.date<sale.date||toMicros(prior)+toMicros(qty)>toMicros(sold))throw new Error('La garantía supera las unidades vendidas o tiene fecha anterior a la venta.');const next=copy(state);const record={...input,quantity:qty,id:id(),status:'quarantined' as const,recordedBy:actor.id,createdAt:now(),history:[{date:now(),actorId:actor.id,action:'Devolución recibida en cuarentena; no aumenta stock disponible'}]};next.inventory.warranties.push(record);audit(next,actor,'Garantía recibida en cuarentena',record.id,input.reason,undefined,record);return next;}
export function dispatchWarrantyReplacement(state:InventoryWorkspace,input:{warrantyId:string;warehouseId:string;date:string;reference:string},actor:Actor):InventoryWorkspace{auth(state,actor);const warranty=getInventoryState(state).warranties.find(row=>row.id===input.warrantyId);if(!warranty||warranty.status!=='quarantined')throw new Error('La garantía no está pendiente de reemplazo.');writable(state,'finished',input.date);if(input.date<warranty.date)throw new Error('El reemplazo no puede ser anterior a la devolución.');warehouse(state,input.warehouseId,actor);text(input.reference,'La orden de garantía');if(getInventoryState(state).warranties.some(row=>row.replacementReference===input.reference)||getInventoryState(state).sales.some(row=>row.reference===input.reference))throw new Error('La referencia de reemplazo ya existe.');const next=copy(state);movement(next,{itemId:warranty.itemId,warehouseId:input.warehouseId,quantity:warranty.quantity},actor,{date:input.date,direction:'out',kind:'warranty_replacement',sourceKey:`warranty:${warranty.id}`,sourceReference:input.reference,responsible:actor.name,support:warranty.photo,notes:warranty.reason});const record=next.inventory.warranties.find(row=>row.id===warranty.id)!;record.status='replaced';record.replacementReference=input.reference;record.replacementWarehouseId=input.warehouseId;record.replacementDate=input.date;record.history.push({date:now(),actorId:actor.id,action:'Reemplazo despachado de stock aceptado; sin segunda venta'});audit(next,actor,'Reemplazo por garantía despachado sin segunda venta',record.id,input.reference,warranty,record);return next;}
export function disposeInventoryWarranty(state:InventoryWorkspace,input:{warrantyId:string;date:string;reason:string},actor:Actor):InventoryWorkspace{auth(state,actor);const warranty=getInventoryState(state).warranties.find(row=>row.id===input.warrantyId);if(!warranty||warranty.status==='disposed')throw new Error('La garantía no existe o ya fue dada de baja.');warehouse(state,warranty.warehouseId,actor);writable(state,'finished',input.date);text(input.reason,'La justificación de la baja',5);if(input.date<warranty.date)throw new Error('La baja no puede ser anterior a la devolución.');const next=copy(state);const record=next.inventory.warranties.find(row=>row.id===warranty.id)!;record.status='disposed';record.disposedAt=input.date;record.history.push({date:now(),actorId:actor.id,action:`Producto defectuoso dado de baja: ${input.reason}`});audit(next,actor,'Producto defectuoso dado de baja desde cuarentena',record.id,input.reason,warranty,record);return next;}

export function disposeInventoryAsset(state:InventoryWorkspace,input:{itemId:string;warehouseId:string;date:string;kind:'theft'|'damage';reason:string;responsible:string;photo?:Support;support:Support;replacementNotes?:string},actor:Actor):InventoryWorkspace{auth(state,actor);const product=item(state,input.itemId);if(product.inventoryType!=='asset')throw new Error('La referencia debe ser un activo.');warehouse(state,input.warehouseId,actor);writable(state,'asset',input.date);if(!['theft','damage'].includes(input.kind))throw new Error('Selecciona hurto o daño.');text(input.reason,'El relato y justificación',5);text(input.responsible,'El responsable del registro');support(input.support);if(input.kind==='damage')support(input.photo!,true);const next=copy(state);const reference=`asset-disposal:${id()}`;movement(next,{itemId:product.id,warehouseId:input.warehouseId,quantity:'1.000000',unitValue:product.unitValue},actor,{date:input.date,direction:'out',kind:input.kind==='theft'?'asset_theft':'asset_damage',sourceKey:reference,sourceReference:reference,responsible:input.responsible,support:input.photo??input.support,notes:`${input.reason}${input.replacementNotes?`; reposición/responsable declarado: ${input.replacementNotes}`:''}`});audit(next,actor,'Baja de activo documentada; sin presumir cobro',reference,input.reason,undefined,{...input,photo:input.photo});return next;}

export function prepareScrapSale(state:InventoryWorkspace,input:{itemId:string;warehouseId:string;quantity:Quantity;date:string;sourceReference:string;responsible:string;support:Support},actor:Actor):InventoryWorkspace{auth(state,actor);support(input.support);text(input.sourceReference,'El acta de preparación');text(input.responsible,'El responsable');const line=checkedLines(state,[input],actor,input.date,['scrap'])[0];if(getInventoryState(state).scrapPreparations.some(row=>row.sourceReference===input.sourceReference))throw new Error('La preparación ya fue registrada.');if(toMicros(getInventoryStock(state,{...line,asOfDate:input.date}).available)<toMicros(line.quantity))throw new Error('La preparación supera el peso disponible.');const next=copy(state);const record={...input,quantity:line.quantity,id:id(),status:'prepared' as const,createdBy:actor.id,createdAt:now()};next.inventory.scrapPreparations.push(record);audit(next,actor,'Peso preparado para venta reservado; independiente del conteo mensual',record.id,input.sourceReference,undefined,record);return next;}
export function dispatchScrapSale(state:InventoryWorkspace,input:{preparationId:string;date:string;quantity:Quantity;unitPrice:Money;buyer:string;reference:string;support:Support;notes?:string},actor:Actor):InventoryWorkspace{auth(state,actor);const preparation=getInventoryState(state).scrapPreparations.find(row=>row.id===input.preparationId);if(!preparation||preparation.status!=='prepared')throw new Error('La preparación no está disponible para despacho.');const line=checkedLines(state,[{itemId:preparation.itemId,warehouseId:preparation.warehouseId,quantity:input.quantity}],actor,input.date,['scrap'])[0];if(input.date<preparation.date||toMicros(line.quantity)>toMicros(preparation.quantity))throw new Error('El despacho supera el peso preparado o tiene fecha anterior.');support(input.support);text(input.buyer,'El comprador');text(input.reference,'La factura o referencia de despacho');if(getInventoryState(state).sales.some(row=>row.reference===input.reference))throw new Error('La factura ya existe.');const unitPrice=money(input.unitPrice);if(toCents(unitPrice)<0n)throw new Error('El precio no puede ser negativo.');const next=copy(state);const dispatchId=id();const saleId=id();const totalValue=quantityValue(line.quantity,unitPrice);movement(next,line,actor,{date:input.date,direction:'out',kind:'scrap_dispatch',sourceKey:`scrap-dispatch:${dispatchId}`,sourceReference:input.reference,responsible:input.buyer,support:input.support,totalValue,notes:input.notes},toMicros(preparation.quantity));next.inventory.scrapPreparations.find(row=>row.id===preparation.id)!.status='dispatched';next.inventory.scrapPreparations.find(row=>row.id===preparation.id)!.dispatchId=dispatchId;next.inventory.sales.push({id:saleId,reference:input.reference,date:input.date,buyer:input.buyer,lines:[{...line,unitPrice,totalValue}],support:input.support,totalValue,kind:'scrap',sourceReference:input.reference,notes:input.notes??'',settlements:[],createdBy:actor.id,createdAt:now()});next.inventory.scrapDispatches.push({id:dispatchId,preparationId:preparation.id,date:input.date,quantity:line.quantity,unitPrice,buyer:input.buyer,reference:input.reference,support:input.support,saleId,returnedQuantity:'0.000000',difference:line.quantity,status:'pending_recognition',notes:input.notes??'',createdBy:actor.id,createdAt:now(),history:[]});audit(next,actor,'Chatarra despachada con precio por operación; pendiente de peso reconocido y recaudo',dispatchId,input.reference,undefined,{quantity:line.quantity,totalValue});return next;}
export function recognizeScrapDispatch(state:InventoryWorkspace,input:{dispatchId:string;date:string;quantity:Quantity;reference:string;support:Support;notes?:string},actor:Actor):InventoryWorkspace{auth(state,actor);const dispatch=getInventoryState(state).scrapDispatches.find(row=>row.id===input.dispatchId);if(!dispatch||dispatch.recognizedQuantity!==undefined)throw new Error('El despacho no existe o ya tiene reconocimiento; una corrección requiere solicitud autorizada.');const prep=getInventoryState(state).scrapPreparations.find(row=>row.id===dispatch.preparationId)!;warehouse(state,prep.warehouseId,actor);writable(state,'scrap',input.date);if(input.date<dispatch.date)throw new Error('El reconocimiento no puede ser anterior al despacho.');const recognized=validateItemQuantity(item(state,prep.itemId),input.quantity,false);if(toMicros(recognized)+toMicros(dispatch.returnedQuantity)>toMicros(dispatch.quantity))throw new Error('El peso reconocido y retornado supera el despachado.');text(input.reference,'La factura definitiva');support(input.support);const originalSale=getInventoryState(state).sales.find(row=>row.id===dispatch.saleId)!;if(getInventoryState(state).sales.some(row=>row.id!==originalSale.id&&row.reference===input.reference))throw new Error('La factura definitiva ya existe.');const finalValue=quantityValue(recognized,dispatch.unitPrice);const allocated=add(...getInventoryState(state).collections.filter(row=>row.saleId===originalSale.id).map(row=>row.amount),...getInventoryState(state).supplierOffsets.filter(row=>row.saleId===originalSale.id).map(row=>row.amount));if(toCents(allocated)>toCents(finalValue))throw new Error('La factura definitiva no puede ser menor que los cobros y compensaciones ya aplicados.');writable(state,'scrap',originalSale.date);const next=copy(state);const finalSale=next.inventory.sales.find(row=>row.id===originalSale.id)!;finalSale.history??=[];if(!finalSale.history.length)finalSale.history.push({date:originalSale.date,action:'Factura original de despacho',reference:originalSale.reference,totalValue:originalSale.totalValue,support:originalSale.support,actorId:originalSale.createdBy});finalSale.reference=input.reference;finalSale.lines=finalSale.lines.map(row=>({...row,quantity:recognized,totalValue:finalValue}));finalSale.totalValue=finalValue;finalSale.support=input.support;finalSale.history.push({date:input.date,action:'Factura definitiva por peso reconocido',reference:input.reference,totalValue:finalValue,support:input.support,actorId:actor.id});const record=next.inventory.scrapDispatches.find(row=>row.id===dispatch.id)!;record.recognizedQuantity=recognized;record.difference=subtractQuantity(subtractQuantity(record.quantity,recognized),record.returnedQuantity);record.status=record.difference==='0.000000'?'matched':'difference';record.history.push({date:input.date,actorId:actor.id,action:'Peso definitivo reconocido',quantity:recognized,support:input.support,sourceReference:input.reference});audit(next,actor,'Peso de chatarra reconocido sin falsear el despacho original',record.id,input.reference,dispatch,record);return next;}
export function returnScrap(state:InventoryWorkspace,input:{dispatchId:string;date:string;quantity:Quantity;reference:string;support:Support},actor:Actor):InventoryWorkspace{auth(state,actor);const dispatch=getInventoryState(state).scrapDispatches.find(row=>row.id===input.dispatchId);if(!dispatch)throw new Error('El despacho no existe.');const prep=getInventoryState(state).scrapPreparations.find(row=>row.id===dispatch.preparationId)!;const line=checkedLines(state,[{itemId:prep.itemId,warehouseId:prep.warehouseId,quantity:input.quantity}],actor,input.date,['scrap'])[0];if(input.date<dispatch.date||toMicros(dispatch.returnedQuantity)+toMicros(line.quantity)+toMicros(dispatch.recognizedQuantity??'0.000000')>toMicros(dispatch.quantity))throw new Error('El retorno y el peso reconocido superan el despacho original.');support(input.support);text(input.reference,'El comprobante del retorno');const next=copy(state);movement(next,line,actor,{date:input.date,direction:'in',kind:'scrap_return',sourceKey:`scrap-return:${input.reference}`,sourceReference:input.reference,responsible:actor.name,support:input.support});const record=next.inventory.scrapDispatches.find(row=>row.id===dispatch.id)!;record.returnedQuantity=addQuantity(record.returnedQuantity,line.quantity);record.difference=subtractQuantity(subtractQuantity(record.quantity,record.recognizedQuantity??'0.000000'),record.returnedQuantity);record.status=record.recognizedQuantity===undefined?'pending_recognition':record.difference==='0.000000'?'matched':'difference';record.history.push({date:input.date,actorId:actor.id,action:'Retorno físico incorporado',quantity:line.quantity,support:input.support,sourceReference:input.reference});audit(next,actor,'Retorno de chatarra vinculado al despacho',record.id,input.reference,dispatch,record);return next;}

export function registerInventoryPrice(state:InventoryWorkspace,input:{itemId:string;month:string;unitPrice:Money;cashTransactionIds:string[];responsible:string;support:Support;notes?:string},actor:Actor):InventoryWorkspace{auth(state,actor);const product=item(state,input.itemId);if(!['raw_material','supply'].includes(product.inventoryType))throw new Error('El registro de precios de cierre corresponde a materiales e insumos.');inventoryMonthBounds(input.month);writable(state,product.inventoryType,`${input.month}-01`);const unitPrice=money(input.unitPrice);if(toCents(unitPrice)<0n)throw new Error('El precio no puede ser negativo.');support(input.support);text(input.responsible,'El responsable del precio');if(!input.cashTransactionIds.length||new Set(input.cashTransactionIds).size!==input.cashTransactionIds.length||input.cashTransactionIds.some(cashId=>!state.transactions.some(row=>row.id===cashId&&row.status==='posted'&&!row.reversedBy&&row.kind==='expense')))throw new Error('Referencia compras reales de Caja para documentar el precio manual, sin promedio automático.');const next=copy(state);const previous=next.inventory.prices.filter(row=>row.itemId===product.id&&row.month===input.month);const record={...input,unitPrice,id:id(),version:previous.length+1,recordedBy:actor.id,createdAt:now(),notes:input.notes??''};next.inventory.prices.push(record);audit(next,actor,'Precio manual del período documentado; conserva versiones y compras fuente',record.id,input.month,previous.at(-1),record);return next;}
export function requestInventoryAuthorization(state:InventoryWorkspace,input:{kind:'origin_omission'|'emergency_adjustment'|'scrap_loss'|'closed_invoice'|'closed_lot';inventoryType:InventoryType;itemId?:string;warehouseId?:string;quantity?:Quantity;entityId?:string;month?:string;reason:string;support:Support},actor:Actor):InventoryWorkspace{auth(state,actor);if(!TYPES.includes(input.inventoryType)||!['origin_omission','emergency_adjustment','scrap_loss','closed_invoice','closed_lot'].includes(input.kind))throw new Error('La solicitud de autorización es inválida.');text(input.reason,'La justificación',5);support(input.support);if(input.warehouseId)warehouse(state,input.warehouseId,actor);if(input.itemId&&item(state,input.itemId).inventoryType!==input.inventoryType)throw new Error('La referencia no corresponde al inventario.');if(input.month)inventoryMonthBounds(input.month);if(input.kind.startsWith('closed_')&&!input.entityId)throw new Error('Vincula la factura o lote del período cerrado.');const next=copy(state);const before=input.kind==='closed_lot'?next.inventory.lots.find(row=>row.id===input.entityId):input.kind==='closed_invoice'?next.inventory.sales.find(row=>row.id===input.entityId):input.itemId?next.inventory.items.find(row=>row.id===input.itemId):undefined;const record={...input,quantity:input.quantity===undefined?undefined:quantity(input.quantity),id:id(),requiredRole:input.kind.startsWith('closed_')?'owner' as const:'owner_or_admin' as const,status:'pending_institutional' as const,requestedBy:actor.id,createdAt:now(),before:before?JSON.stringify(before,(key,value)=>key==='dataUrl'?'[evidencia preservada]':value).slice(0,2000):'Solicitud sin modificación de existencias'};next.inventory.requests.push(record);audit(next,actor,'Autorización de Inventarios solicitada; sin aplicación local',record.id,input.reason,undefined,record);return next;}

export function getInventoryAlerts(state:InventoryWorkspace,today=todayBogota()):InventoryAlert[]{validateDate(today);const inventory=getInventoryState(state);const alerts=structuredClone(inventory.alerts.filter(row=>row.date<=today));const push=(alert:Omit<InventoryAlert,'status'|'history'>)=>{if(!alerts.some(row=>row.id===alert.id))alerts.push({...alert,status:'open',history:[]});};for(const product of inventory.items.filter(row=>row.active&&row.inventoryType==='finished'&&inventoryItemEffectiveDate(state,row)<=today))for(const location of inventory.warehouses.filter(row=>row.active)){const count=inventory.counts.filter(row=>row.inventoryType==='finished'&&row.date===today&&row.lines.some(line=>line.itemId===product.id&&line.warehouseId===location.id)).at(-1);const current=inventory.movements.filter(row=>row.itemId===product.id&&row.warehouseId===location.id&&row.date<=today);if(!count||current.some(row=>!count.movementIds.includes(row.id)))push({id:`inventory-daily:${product.id}:${location.id}:${today}`,type:'daily_count_missing',title:'Conteo diario de producto terminado pendiente',description:'Se requiere acta, responsable y conteo actualizado de la referencia en esta bodega.',severity:'warning',priority:3,date:today,itemId:product.id,warehouseId:location.id,locationId:location.locationId});}
  for(const lot of inventory.lots.filter(row=>row.date<=today&&row.status==='disputed')){const location=inventory.warehouses.find(row=>row.id===lot.lines[0]?.warehouseId);push({id:`inventory-lot:${lot.id}`,type:'lot_discrepancy',title:'Lote con conformidades discrepantes',description:lot.reference,severity:'warning',priority:3,date:lot.date,locationId:location?.locationId});}
  for(const dispatch of inventory.scrapDispatches.filter(row=>row.date<=today&&row.status!=='matched')){const preparation=inventory.scrapPreparations.find(row=>row.id===dispatch.preparationId);const location=inventory.warehouses.find(row=>row.id===preparation?.warehouseId);push({id:`inventory-scrap:${dispatch.id}`,type:'scrap_weight_difference',title:'Despacho de chatarra sin conciliación definitiva',description:`${dispatch.reference}; diferencia pendiente ${dispatch.difference}.`,severity:'warning',priority:3,date:dispatch.date,itemId:preparation?.itemId,warehouseId:preparation?.warehouseId,locationId:location?.locationId,quantity:dispatch.difference});}
  for(const sale of inventory.sales.filter(row=>row.date<=today&&['asset','scrap'].includes(row.kind))){const settled=add(...inventory.collections.filter(row=>row.saleId===sale.id&&row.date<=today).map(row=>row.amount),...inventory.supplierOffsets.filter(row=>row.saleId===sale.id&&row.date<=today).map(row=>row.amount));if(toCents(settled)<toCents(sale.totalValue)){const location=inventory.warehouses.find(row=>row.id===sale.lines[0]?.warehouseId);push({id:`inventory-uncollected:${sale.id}`,type:'sale_uncollected',title:'Venta de activo o chatarra pendiente de recaudo',description:`${sale.reference}; facturado ${sale.totalValue}; confirmado ${settled}.`,severity:'warning',priority:3,date:sale.date,locationId:location?.locationId});}}
  for(const request of inventory.requests.filter(row=>row.createdAt.slice(0,10)<=today)){const product=request.itemId?inventory.items.find(row=>row.id===request.itemId):undefined;const location=inventory.warehouses.find(row=>row.id===request.warehouseId);push({id:`inventory-request:${request.id}`,type:'authorization_pending',title:'Autorización institucional de Inventarios pendiente',description:request.reason,severity:'warning',priority:3,date:request.createdAt.slice(0,10),itemId:product?.id,warehouseId:location?.id,locationId:location?.locationId});}
  return alerts.map(row=>({...row,...(row.priority===2?{type:'finished_product_shortage'}:{}),inventoryType:row.itemId?inventory.items.find(product=>product.id===row.itemId)?.inventoryType:row.id.startsWith('inventory-lot:')?'finished' as const:row.id.startsWith('inventory-scrap:')?'scrap' as const:row.id.startsWith('inventory-uncollected:')?inventory.sales.find(sale=>row.id===`inventory-uncollected:${sale.id}`)?.kind:row.id.startsWith('inventory-request:')?inventory.requests.find(request=>row.id===`inventory-request:${request.id}`)?.inventoryType:row.inventoryType})).sort((a,b)=>a.priority-b.priority||b.date.localeCompare(a.date));}

function priceFor(state:InventoryWorkspace,product:InventoryItem,cutoff:string):Money|null{const inventory=getInventoryState(state);if(product.inventoryType==='scrap')return null;if(['raw_material','supply'].includes(product.inventoryType))return inventory.prices.filter(row=>row.itemId===product.id&&row.month===cutoff.slice(0,7)).at(-1)?.unitPrice??null;const source=inventory.movements.filter(row=>row.itemId===product.id&&row.date<=cutoff&&row.direction==='in').at(-1);if(source?.unitValue!==undefined)return source.unitValue;if(source?.totalValue!==undefined&&source.quantity==='1.000000')return source.totalValue;return product.unitValue??null;}
export function scopeInventoryReport(source:InventoryReport,input:{locationId?:string;warehouseId?:string}):InventoryReport{const report=structuredClone(source);if(!input.locationId&&!input.warehouseId)return report;report.rows=report.rows.filter(row=>(!input.locationId||row.locationId===input.locationId)&&(!input.warehouseId||row.warehouseId===input.warehouseId));const warehouses=new Set(report.rows.map(row=>row.warehouseId));const items=new Set(report.rows.map(row=>row.itemId));report.movements=report.movements.filter(row=>warehouses.has(row.warehouseId));report.issues=report.issues.filter(row=>(!input.locationId||row.locationId===input.locationId)&&(!input.warehouseId||row.warehouseId===input.warehouseId));report.prices=report.prices?.filter(row=>items.has(row.itemId));report.authorizations=report.authorizations?.filter(row=>!!row.warehouseId&&warehouses.has(row.warehouseId));const counts=new Set(report.rows.map(row=>row.countId));report.countDocuments=report.countDocuments?.filter(row=>counts.has(row.id));report.totalValue=report.rows.some(row=>row.theoreticalValue===null)?null:add(...report.rows.map(row=>row.theoreticalValue!));report.reconciled=report.rows.every(row=>row.difference==='0.000000')&&!report.issues.some(row=>row.status==='open');return report;}
export function getInventoryReport(state:InventoryWorkspace,input:InventoryReportInput):InventoryReport{validateDate(input.startDate);validateDate(input.endDate);if(input.startDate>input.endDate)throw new Error('El inicio debe ser anterior al corte.');if(!TYPES.includes(input.inventoryType))throw new Error('Inventario inválido.');const inventory=getInventoryState(state);const closedSnapshot=inventory.monthClosures.find(row=>row.inventoryType===input.inventoryType&&`${row.month}-01`===input.startDate&&inventoryMonthBounds(row.month).endDate===input.endDate);if(closedSnapshot)return scopeInventoryReport(closedSnapshot.report,input);if(input.locationId&&!state.locations.some(row=>row.id===input.locationId))throw new Error('La sede no existe.');if(input.warehouseId&&!inventory.warehouses.some(row=>row.id===input.warehouseId))throw new Error('La bodega no existe.');const locations=inventory.warehouses.filter(row=>(!input.locationId||row.locationId===input.locationId)&&(!input.warehouseId||row.id===input.warehouseId));const allowed=new Set(locations.map(row=>row.id));const prior=new Date(Date.parse(`${input.startDate}T12:00:00Z`)-86400000).toISOString().slice(0,10);const report:InventoryReport={inventoryType:input.inventoryType,startDate:input.startDate,endDate:input.endDate,generatedAt:now(),version:1,status:'draft',scope:'local',rows:[],movements:inventory.movements.filter(row=>row.inventoryType===input.inventoryType&&row.date>=input.startDate&&row.date<=input.endDate&&allowed.has(row.warehouseId)),issues:getInventoryAlerts(state,input.endDate).filter(row=>row.inventoryType===input.inventoryType&&(!row.itemId||inventory.items.some(product=>product.id===row.itemId&&product.inventoryType===input.inventoryType))&&(!row.warehouseId||allowed.has(row.warehouseId))&&(!input.locationId||row.locationId===input.locationId)&&!(row.type==='lot_discrepancy'&&input.inventoryType!=='finished')&&!(row.type==='scrap_weight_difference'&&input.inventoryType!=='scrap')&&!(row.type==='sale_uncollected'&&!['asset','scrap'].includes(input.inventoryType))),totalValue:'0.00',reconciled:true,prices:inventory.prices.filter(row=>row.month===input.endDate.slice(0,7)&&inventory.items.some(product=>product.id===row.itemId&&product.inventoryType===input.inventoryType)).map(row=>({...row,support:{name:row.support.name,type:row.support.type,size:row.support.size}})),authorizations:inventory.requests.filter(row=>row.inventoryType===input.inventoryType&&(!row.warehouseId||allowed.has(row.warehouseId))).map(row=>({...row,support:{name:row.support.name,type:row.support.type,size:row.support.size}}))};
  for(const product of inventory.items.filter(row=>row.inventoryType===input.inventoryType&&inventoryItemEffectiveDate(state,row)<=input.endDate))for(const location of locations){const stock=getInventoryStock(state,{itemId:product.id,warehouseId:location.id,asOfDate:input.endDate});const rows=report.movements.filter(row=>row.itemId===product.id&&row.warehouseId===location.id);const count=inventory.counts.filter(row=>row.inventoryType===input.inventoryType&&row.date<=input.endDate&&row.date>=input.startDate&&row.lines.some(line=>line.itemId===product.id&&line.warehouseId===location.id)).at(-1);const physical=count?.lines.find(row=>row.itemId===product.id&&row.warehouseId===location.id);const unitPrice=priceFor(state,product,input.endDate);const counted=physical?.quantity??null;const difference=counted===null?null:subtractQuantity(counted,stock.theoretical);report.rows.push({itemId:product.id,code:product.code,description:product.description,unit:product.unit,warehouseId:location.id,warehouseName:location.name,locationId:location.locationId,opening:getInventoryStock(state,{itemId:product.id,warehouseId:location.id,asOfDate:prior}).theoretical,incoming:addQuantity(...rows.filter(row=>row.direction==='in').map(row=>row.quantity)),outgoing:addQuantity(...rows.filter(row=>row.direction==='out').map(row=>row.quantity)),...stock,counted,difference,unitPrice,theoreticalValue:unitPrice===null?null:quantityValue(stock.theoretical,unitPrice),countedValue:unitPrice===null||counted===null?null:quantityValue(counted,unitPrice),differenceValue:unitPrice===null||difference===null?null:quantityValue(difference,unitPrice),countId:count?.id,countDate:count?.date,responsible:count?.responsible});}
  report.prices=report.prices?.filter(row=>report.rows.some(line=>line.itemId===row.itemId));report.countDocuments=inventory.counts.filter(row=>report.rows.some(line=>line.countId===row.id)).map(row=>({id:row.id,date:row.date,sourceReference:row.sourceReference,responsible:row.responsible,support:{name:row.support.name,type:row.support.type,size:row.support.size}}));report.totalValue=report.rows.some(row=>row.theoreticalValue===null)?null:add(...report.rows.map(row=>row.theoreticalValue!));report.reconciled=inventory.origins.some(row=>row.inventoryType===input.inventoryType&&row.status==='posted'&&row.date<=input.endDate)&&report.rows.every(row=>row.difference==='0.000000')&&!report.issues.some(row=>row.status==='open');const closure=inventory.monthClosures.find(row=>row.inventoryType===input.inventoryType&&`${row.month}-01`===input.startDate&&inventoryMonthBounds(row.month).endDate===input.endDate);if(closure){report.version=closure.version;report.status='closed';report.closedAt=closure.closedAt;report.closedBy=closure.closedBy;}return report;}
export function getInventoryMonthChecklist(state:InventoryWorkspace,input:{inventoryType:InventoryType;month:string}):{inventoryType:InventoryType;month:string;canClose:boolean;items:{id:string;label:string;blocking:boolean;entityId?:string}[];report:InventoryReport}{const bounds=inventoryMonthBounds(input.month);const inventory=getInventoryState(state);const report=getInventoryReport(state,{inventoryType:input.inventoryType,...bounds});const items:{id:string;label:string;blocking:boolean;entityId?:string}[]=[];const push=(id:string,label:string,entityId?:string)=>items.push({id,label,entityId,blocking:true});if(!inventory.origins.some(row=>row.inventoryType===input.inventoryType&&row.status==='posted'&&row.date<=bounds.endDate))push('origin','Falta ORIGEN único documentado.');if(!inventory.counts.some(row=>row.inventoryType===input.inventoryType&&row.purpose==='monthly'&&row.date>=bounds.startDate&&row.date<=bounds.endDate))push('monthly-count','Falta acta mensual documentada del inventario.');if(bounds.endDate>todayBogota())push('future','El mes calendario todavía no ha terminado.');if(inventory.monthClosures.some(row=>row.inventoryType===input.inventoryType&&row.month===input.month))push('closed','El inventario de ese mes ya está cerrado.');for(const row of report.rows){const count=inventory.counts.find(item=>item.id===row.countId);if(!count||count.purpose!=='monthly')push(`count:${row.itemId}:${row.warehouseId}`,'Falta acta mensual con responsable y soporte.',row.itemId);else if(inventory.movements.some(movement=>movement.itemId===row.itemId&&movement.warehouseId===row.warehouseId&&movement.date<=bounds.endDate&&!count.movementIds.includes(movement.id)))push(`stale:${row.itemId}:${row.warehouseId}`,'El acta quedó obsoleta después de movimientos posteriores.',row.itemId);if(row.difference!==null&&row.difference!=='0.000000')push(`difference:${row.itemId}:${row.warehouseId}`,'Hay una diferencia física sin conciliación.',row.itemId);if(['raw_material','supply'].includes(input.inventoryType)&&row.unitPrice===null)push(`price:${row.itemId}`,'Falta precio manual del período con compras reales de Caja.',row.itemId);}for(const issue of report.issues.filter(row=>row.status==='open'))push(issue.id,issue.title,issue.itemId);for(const request of inventory.requests.filter(row=>row.inventoryType===input.inventoryType))push(`request:${request.id}`,'Hay autorización institucional pendiente.',request.id);return {...input,canClose:items.length===0,items,report};}
export function closeInventoryMonth(state:InventoryWorkspace,input:{inventoryType:InventoryType;month:string;notes?:string},actor:Actor):InventoryWorkspace{auth(state,actor,undefined,['owner','admin']);const checklist=getInventoryMonthChecklist(state,input);if(!checklist.canClose)throw new Error(`No se puede cerrar: ${checklist.items.map(row=>row.label).join(' ')}`);for(const location of getInventoryState(state).warehouses)auth(state,actor,location.locationId,['owner','admin']);const next=copy(state);const closedAt=now();const record={id:id(),inventoryType:input.inventoryType,month:input.month,status:'closed' as const,scope:'local' as const,version:1,report:{...structuredClone(checklist.report),status:'closed' as const,closedAt,closedBy:actor.id},closedBy:actor.id,closedAt,notes:input.notes??''};next.inventory.monthClosures.push(record);audit(next,actor,'Inventario cerrado localmente; autorización institucional no simulada',record.id,input.month,undefined,{inventoryType:record.inventoryType,month:record.month,version:record.version,totalValue:record.report.totalValue});return next;}
